package org.jsoup.helper;

import org.junit.Test;
import static org.junit.Assert.*;
import java.io.UnsupportedEncodingException;
import java.net.IDN;
import java.net.MalformedURLException;
import java.net.URI;
import java.net.URISyntaxException;
import java.net.URL;
import java.net.URLDecoder;
import java.net.URLEncoder;
import static org.mockito.Mockito.*;

public class UrlBuilderTest {

    @Test
    public void newUrlBuilderWithValidUrl() {
        UrlBuilder builder = new UrlBuilder(new URL("http://example.com"));
        assertEquals(new URL("http://example.com"), builder.build());
    }

    @Test
    public void newUrlBuilderWithInvalidUrl() throws MalformedURLException {
        UrlBuilder builder = mock(UrlBuilder.class);
        when(builder.build()).thenReturnThrowingException(MalformedURLException::new);
        assertThrows(MalformedURLException.class, () -> builder.build());
    }

    @Test
    public void build_url_with_query_params() {
        UrlBuilder builder = new UrlBuilder("http://example.com", 1);
        assertEquals("http://example.com?param=value&other=abc", builder.build().toString());
    }

    @Test
    public void build_url_without_query_params() {
        UrlBuilder builder = new UrlBuilder("http://example.com", 1);
        assertEquals("http://example.com", builder.build().toString());
    }

}

class UrlBuilder {
    private String url;
    private int port;

    public UrlBuilder(String url, int port) {
        this.url = url;
        this.port = port;
    }

    public URL build() throws MalformedURLException {
        return new URL(url + (port > 0 ? ":" + port : ""));
    }
}
